"""Writing generated files, and the user's files the rice changes a part of."""
import os
import re
import tempfile

GENERATED = "Generated by ~/.config/hypr/scripts/themegen.py, do not edit by hand."


def write(path, text):
    write_bytes(path, text.encode())


def write_bytes(path, data):
    """Atomically: a reader, or a crash halfway, sees the old file or the new one, never a cut one. The
    file keeps its permissions. A symlink at path is replaced by the file, not written through: a
    generated file once linked to a theme's own must not overwrite it. To write through a link to a
    file of the user's (a settings.json kept in a dotfiles repo), pass path.resolve()."""
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o7777 if path.exists() and not path.is_symlink() else new_file_mode()
    descriptor, temporary = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.", suffix=".tmp")
    try:
        with os.fdopen(descriptor, "wb") as out:
            out.write(data)
        os.chmod(temporary, mode)
        os.replace(temporary, path)
    except BaseException:
        os.unlink(temporary)
        raise


def new_file_mode():
    """What open() would give a new file: rw for everyone, minus the umask."""
    umask = os.umask(0)
    os.umask(umask)
    return 0o666 & ~umask


def without_block(text, begin, end):
    """text without the block from the marker line begin to the marker line end."""
    return re.sub(rf"{re.escape(begin)}.*?{re.escape(end)}\n?", "", text, flags=re.S)


def with_block(text, begin, end, block_lines):
    """text with the marked block rewritten at its end; everything outside the block stays."""
    text = without_block(text, begin, end)
    if text and not text.endswith("\n"):
        text += "\n"
    return text + "\n".join([begin, *block_lines, end]) + "\n"
